import { Component, Element, Event, EventEmitter, h, Host, Prop, State } from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { Value, ValueField } from '@src/components/ks-value-field/types';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';

@Component({
  tag: 'ks-combobox',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsCombobox extends FormBaseComponent<Value[]> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsComboboxElement;

  /** Controls the selected raw values rendered as tags in the combobox. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: Value[];

  /** Sets the initial selected raw values when the combobox is uncontrolled. */
  @Prop() defaultValue?: Value[];
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: Value[];

  /** Controls whether combobox is disabled. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;

  /** Status of the combobox component. */
  @Prop() @FormContextValueReconcile() status?: Status;

  /** Whether the combobox can be cleared with the built-in clear action. */
  @Prop() clearable = true;

  /** Controls the height of the tag value field. Use a string or number for a fixed height, or pass `{ min, max }` to let it grow within a range. */
  @Prop() valueFieldHeight?: string | number | { min?: string | number; max?: string | number };

  /** Sets the placeholder text shown when no value or input text is present. */
  @Prop() placeholder?: string;

  /** Whether to collapse multiple selected items into a summary view. When true, selected items will be displayed in a collapsed format with a count indicator. When false, all selected items will be fully displayed. */
  @Prop() tagsEllipsis = true;

  /** Controls whether selected tags display remove buttons. */
  @Prop() closeable = true;

  /** Emitted when the selected values change. Emits the updated array of raw values. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<Value[]>;

  /** Emitted when the combobox is cleared. Clears both the selected values and the input text. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;

  /** Emitted when a key is pressed in the combobox input. Emits the native `KeyboardEvent`. */
  @Event({ bubbles: false, composed: false }) ksInputKeyDown!: EventEmitter<KeyboardEvent>;

  /** Controls the current text shown in the combobox input. */
  @Prop() inputValue?: string;

  /** Sets the initial text shown in the combobox input when it is uncontrolled. */
  @Prop() inputDefaultValue?: string;
  @Uncontrollable('inputValue', 'inputDefaultValue', 'ksInputChange') @State() internalInputValueState?: string;

  /** Emitted when the combobox input text changes. Emits the updated input string. */
  @Event({ bubbles: false, composed: false }) ksInputChange!: EventEmitter<string>;

  /** Controls whether the typed input text is cleared after the selected values change. */
  @Prop() autoClearInputValue = true;

  /**
   * Maps the selected raw values to the `ValueField[]` used to render tags in the combobox. Use this to customize each tag's label, status, disabled state, style, or popover.
   *
   * If not provided, the component renders each value with `value.toString()` as its label.
   *
   * Example: `(values) => values.map((value) => ({ value, label: `Custom ${value}` }))`
   */
  @Prop() mapValuesToValueFields?: (values: Value[]) => ValueField[] = (values) =>
    values.map((value) => ({ value, label: value.toString() }));

  @State() focused = false;

  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor() {
    super();
  }

  render() {
    return (
      <Host class="KsCombobox">
        <ks-value-field
          type="tagged"
          disabled={this.disabled}
          status={this.status}
          placeholder={this.placeholder}
          defaultValue={this.mapValuesToValueFields?.(this.defaultValue || []) || []}
          value={this.mapValuesToValueFields?.(this.internalValueState || []) || []}
          clearable={this.clearable}
          valueFieldHeight={this.valueFieldHeight}
          tagsEllipsis={this.tagsEllipsis}
          closeable={this.closeable}
          onKsChange={({ detail: fields }) => (this.internalValueState = fields.map((item) => item.value))}
          onKsClear={(e) => {
            this.ksClear.emit(e.detail);
            this.internalInputValueState = '';
            this.internalValueState = [];
          }}
          onKsInputKeyDown={(e) => this.ksInputKeyDown.emit(e.detail)}
          enableInput
          inputValue={this.internalInputValueState}
          inputDefaultValue={this.inputDefaultValue}
          onKsInputChange={(e) => (this.internalInputValueState = e.detail)}
          autoClearInputValue={this.autoClearInputValue}
          onFocus={() => (this.focused = true)}
          onBlur={() => (this.focused = false)}
          focusElement={this.focused}
          freeSolo
          data-testid="ks-combobox-index-oLUSrY"
        ></ks-value-field>
      </Host>
    );
  }
}
